/// The four marker shapes; severity is never colour alone (DESIGN.md §4).
enum MarkerShapeKind: Sendable { case circle, diamond, triangle, octagon }

extension Severity {
    var color: Color {
        switch self {
        case .minor: .severityMinor
        case .moderate: .severityModerate
        case .severe: .severitySevere
        case .extreme: .severityExtreme
        }
    }

    var markerShape: MarkerShapeKind {
        switch self {
        case .minor: .circle
        case .moderate: .diamond
        case .severe: .triangle
        case .extreme: .octagon
        }
    }

    var markerScale: CGFloat {
        switch self {
        case .minor: 0.8
        case .moderate: 1
        case .severe: 1.15
        case .extreme: 1.3
        }
    }


    /// The shape as a symbol, for badges and text-sized uses where a drawn octagon reads as a circle.
    var sfSymbol: String {
        switch self {
        case .minor: "circle.fill"
        case .moderate: "diamond.fill"
        case .severe: "triangle.fill"
        case .extreme: "exclamationmark.octagon.fill"
        }
    }

    var pulses: Bool { self == .extreme }
}

extension EventKind {
    var sfSymbol: String {
        switch self {
        case .observed: "eye"
        case .warning: "checkmark.seal"
        case .forecast: "clock.arrow.circlepath"
        case .detection: "thermometer.high"
        }
    }
}

